module TopModule (
    input  clk,
    input  x,
    output z
);

    // Internal signals for the three D flip-flops
    reg q0, q1, q2;

    // Assign the complemented outputs for the AND and OR gates
    wire q0_n = ~q0;
    wire q1_n = ~q1;
    wire q2_n = ~q2;

    // D flip-flops with synchronous reset (initial value 0)
    always @(posedge clk) begin
        // D input for flip-flop 0: XOR of x and its own output
        q0 <= x ^ q0;
        // D input for flip-flop 1: AND of x and complemented output of q0
        q1 <= x & q0_n;
        // D input for flip-flop 2: OR of x and complemented output of q1
        q2 <= x | q1_n;
    end

    // Three-input NOR gate: output is Z
    // NOR(a, b, c) = ~(a | b | c)
    assign z = ~(q0 | q1 | q2);

endmodule

