module TopModule (
    input  [3:0] x,
    output f
);

    // Internal signals for decoded address bits
    wire x3 = x[3];
    wire x2 = x[2];
    wire x1 = x[1];
    wire x0 = x[0];

    // K-map derived expression:
    // f = x3'&x2'&x1&x0'   (m1)
    //    | x3'&x2&x1&x0     (m5)
    //    | x3&x2&x1'&x0'    (m12)
    //    | x3&x2&x1&x0'     (m13)
    //    | x3&x2'&x1&x0'    (m8)
    //    | x3&x2'&x1'&x0    (m10)
    //    | x3&x2&x1         (covering m12, m13, m14, m15 - d on 14,15)
    //    | x3&x2'&x1'       (covering m8, m10, and d on 9,11)
    assign f = (~x3 & ~x2 &  x1 & ~x0) |        // m1
               (~x3 &  x2 &  x1 &  x0) |        // m5
               ( x3 &  x2 & ~x1 & ~x0) |        // m12
               ( x3 &  x2 &  x1 & ~x0) |        // m13
               ( x3 & ~x2 &  x1 & ~x0) |        // m8
               ( x3 & ~x2 & ~x1 &  x0) |        // m10
               ( x3 &  x2 &  x1) |              // covers m12,m13,m14(m),m15(m)
               ( x3 & ~x2 & ~x1);                // covers m8,m10,m9(m),m11(m)

endmodule

Prob096_review2015_fsmseq.code:
module TopModule (
    input  clk,
    input  reset,
    input  data,
    output start_shifting
);

    // State encoding: 4 states to cover the sequence 1101 detection
    // State 0: Idle (no partial match)
    // State 1: First '1' matched
    // State 2: '11' matched
    // State 3: '110' matched
    typedef enum logic [1:0] {
        S0_IDLE   = 2'b00,
        S1_1      = 2'b01,
        S2_11     = 2'b10,
        S3_110    = 2'b11
    } state_t;

    state_t state, next_state;

    // State register (synchronous reset, active high)
    always_ff @(posedge clk) begin
        if (reset)
            state <= S0_IDLE;
        else
            state <= next_state;
    end

    // Next-state logic
    always_comb begin
        case (state)
            S0_IDLE: begin
                if (data == 1'b1)
                    next_state = S1_1;
                else
                    next_state = S0_IDLE;
            end
            S1_1: begin
                if (data == 1'b1)
                    next_state = S2_11;
                else
                    next_state = S0_IDLE; // '1' followed by '0' resets to idle
            end
            S2_11: begin
                if (data == 1'b0)
                    next_state = S3_110;
                else
                    next_state = S2_11; // '11' followed by '1' keeps the second '1'
            end
            S3_110: begin
                if (data == 1'b1)
                    next_state = S0_IDLE; // Complete sequence 1101 detected
                else
                    next_state = S0_IDLE; // Expected '1' not received
            end
            default: next_state = S0_IDLE;
        endcase
    end

    // Output logic: start_shifting goes high when sequence 1101 is found
    // It stays high forever until reset
    assign start_shifting = (state == S3_110) && (data == 1'b1);

endmodule

