                3'b110: state <= 2'b01; // Between s[2] and s[1]
                3'b100: state <= 2'b01; // Between s[1] and s[0] (s[0] asserted)
                3'b000: state <= 2'b00; // Below s[0]
                default: state <= state; // No change (should not occur with valid sensors)
            endcase
        end
