    input  clk,
    input  reset,
    input  x,
    output z
);

    // State register: 3 bits for y[2:0]
    reg [2:0] y;

    // Next-state logic (combinational)
    always @(*) begin
        case (y)
            3'b000: y = (x == 1'b1) ? 3'b001 : 3'b000;
            3'b001: y = (x == 1'b1) ? 3'b100 : 3'b001;
            3'b010: y = (x == 1'b1) ? 3'b001 : 3'b010;
            3'b011: y = (x == 1'b1) ? 3'b010 : 3'b001;
            3'b100: y = (x == 1'b1) ? 3'b100 : 3'b011;
            default: y = 3'b000;
        endcase
    end

