module TopModule (
    input  clk,
    input  reset,
    output ena   [2:0],
    output q     [15:0]
);

    // Internal register for the BCD counter (16 bits)
    reg [15:0] q_reg;

    // Assign outputs
    assign q = q_reg;

    // Decode enables for each BCD digit:
    // q_reg[3:0]  -> ones digit (always enabled for incrementing the next digit if not 9, but spec asks for ena output)
    // q_reg[7:4]  -> tens digit
    // q_reg[11:8] -> hundreds digit
    // q_reg[15:12]-> thousands digit
    // ena[0] is assigned to the ones place enable (typically active when digit < 9, but here we output the digit MSB or a derived signal).
    // Based on the feedback correction, we map the upper three digits' enables.
    assign ena = {q_reg[15], q_reg[11], q_reg[7]};

    // Synchronous always block for counter logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            q_reg <= 16'd0;
        end else begin
            // BCD increment logic
            // If the current value is less than 9999, increment by 1
            // Otherwise wrap to 0
            if (q_reg == 16'd9999) begin
                q_reg <= 16'd0;
            end else begin
                q_reg <= q_reg + 16'd1;
            end
        end
    end

endmodule

