module TopModule (
    input  d,
    input  done_counting,
    input  ack,
    input  state [9:0],
    output B3_next,
    output S_next,
    output S1_next,
    output Count_next,
    output Wait_next,
    output done,
    output counting,
    output shift_ena
);

    // Internal wires for decoded next-state signals
    wire next_S;
    wire next_S1;
    wire next_S11;
    wire next_S110;
    wire next_B0;
    wire next_B1;
    wire next_B2;
    wire next_B3;
    wire next_Count;
    wire next_Wait;

    // ============================================================
    // Next-state logic (one-hot encoded state transition)
    // ============================================================
    // The current state is provided on the 'state' port (one-hot).
    // We derive the next-state signals by inspection of the FSM diagram.

    // S next-state: from S (d=0) or S1 (d=0) or S110 (d=0)
    assign next_S = (state[0] & ~d) |
                    (state[1] & ~d) |
                    (state[3] & ~d);

    // S1 next-state: from S (d=1) or S11 (d=1)
    assign next_S1 = (state[0] & d) |
                     (state[2] & d);

    // S11 next-state: from S1 (d=1)
    assign next_S11 = (state[1] & d);

    // S110 next-state: from S11 (d=0)
    assign next_S110 = (state[2] & ~d);

    // B0 next-state: from S11 (d=1)
    assign next_B0 = (state[2] & d);

    // B1 next-state: from B0 (always go to next cycle)
    assign next_B1 = next_B0;  // always transition

    // B2 next-state: from B1 (always go to next cycle)
    assign next_B2 = next_B1;  // always transition

    // B3 next-state: from B2 (always go to next cycle)
    assign next_B3 = next_B2;  // always transition

    // Count next-state: from B3 (always go to next cycle)
    assign next_Count = next_B3;  // always transition

    // Wait next-state: from Count (done_counting=1) or staying in Wait with ack=0
    // From Count: done_counting=1 -> Wait
    // From Wait: ack=0 -> Wait, ack=1 -> S (so Wait next-state is 0 when ack=1)
    assign next_Wait = (state[9] & done_counting) | (state[9] & ~ack);

    // ============================================================
    // Output signals for next-state assertions
    // ============================================================
    assign B3_next   = next_B3;
    assign S_next    = next_S;
    assign S1_next   = next_S1;
    assign Count_next= next_Count;
    assign Wait_next = next_Wait;

    // ============================================================
    // Output logic (Moore machine: outputs depend only on state)
    // ============================================================
    // Encoding: (S, S1, S11, S110, B0, B1, B2, B3, Count, Wait)
    //           (bit 0, bit 1, bit 2, bit 3, bit 4, bit 5, bit 6, bit 7, bit 8, bit 9)

    // shift_ena: asserted in B0, B1, B2, B3 states
    assign shift_ena = (state[4] | state[5] | state[6] | state[7]);

    // counting: asserted in Count state
    assign counting = (state[8]);

    // done: asserted in Wait state
    assign done = (state[9]);

endmodule
